const input = $input.first().json;
const st = input.scenarioType || "general_communication";
const scenarios = {
  customer_complaint: {
    role: "khach hang kho tinh phan nan ve dich vu cham tre",
    objective: "xu ly khieu nai, de xuat giai phap, giu chan khach hang",
    difficulty: "cao"
  },
  colleague_conflict: {
    role: "dong nghiep co mau thuan phan cong cong viec",
    objective: "giai quyet mau thuan, duy tri quan he chuyen nghiep",
    difficulty: "trung binh"
  },
  manager_feedback: {
    role: "manager feedback hieu suat thap va deadline tre",
    objective: "tiep nhan feedback tich cuc, lap ke hoach cai thien cu the",
    difficulty: "trung binh"
  },
  new_employee_onboarding: {
    role: "nhan vien moi tuan dau tien can huong dan lam quen moi truong",
    objective: "hoa nhap nhanh, hieu ro quy dinh va ky vong cong ty",
    difficulty: "thap"
  },
  performance_review: {
    role: "HR danh gia hieu suat quy, thao luan muc tieu SMART",
    objective: "danh gia trung thuc, thiet lap muc tieu ro rang, dong thuan",
    difficulty: "cao"
  },
  general_communication: {
    role: "doi tac trong cuoc hop dam phan hop dong dich vu",
    objective: "giao tiep hieu qua, dat thoa thuan co loi cho ca hai",
    difficulty: "trung binh"
  }
};
const sd = scenarios[st] || scenarios.general_communication;
return [{ json: { ...input, scenarioType: st, scenarioData: sd } }];

const session = $input.first().json;
const scenario = $("Load Scenario").first().json.scenarioData;
const routerInput = $("Input from Router").first().json;
return [{ json: {
  sessionId: session.id,
  maskedMessage: routerInput.maskedMessage,
  employeeId: routerInput.employeeId,
  scenarioRole: scenario.role,
  scenarioObjective: scenario.objective,
  scenarioDifficulty: scenario.difficulty
} }];

const output = $input.first().json.output || "";
const scoreMatch = output.match(/\[DANH GIA:([^\]]+)\]/);
let scoring = null;
if (scoreMatch) {
  const p = scoreMatch[1];
  const ex = (k) => {
    const m = p.match(new RegExp(k + '=(\\d+(?:\\.\\d+)?)'));
    return m ? parseFloat(m[1]) : 0;
  };
  const nx = p.match(/nhan_xet=(.+)/);
  scoring = {
    scores: {
      professional: ex('chuyen_nghiep'),
      empathy: ex('dong_cam'),
      problem_solving: ex('giai_quyet'),
      clarity: ex('ro_rang')
    },
    total: ex('tong'),
    feedback: nx ? nx[1].trim() : ''
  };
}
const roleplayResponse = output.replace(/\[DANH GIA:[^\]]+\]/, '').trim();
const sessionId = $("Get/Create Session").first().json.id;
const scenarioType = $("Load Scenario").first().json.scenarioType;
return [{ json: { roleplayResponse, scoring, sessionId, scenarioType } }];
